values.content:
=Analyze this company for outbound sales.

Company: {{ $json.name }}
Website: {{ $json.website_url }}
Industry: {{ $json.industry }}

Return JSON:
{
  "summary": "2-3 sentence overview",
  "pain_points": ["p1", "p2", "p3"],
  "buying_triggers": ["t1", "t2"],
  "ideal_contact_titles": ["VP Sales", "Head of Growth"]
}

parameters.jsCode:
const company = $('Split In Batches').item.json;
let analysis = {};
try {
  const raw = $input.first().json.message?.content || $input.first().json.text || '{}';
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  analysis = { summary: 'Parse error', pain_points: [], buying_triggers: [], ideal_contact_titles: ['CEO'] };
}
return [{ json: { ...company, ...analysis } }];

const company = $('Parse Analysis JSON').item.json;
const people = $input.first().json.people || [];
const person = people[0] || {};
return [{
  json: {
    company_name: company.name,
    website: company.website_url,
    industry: company.industry,
    analysis_summary: company.summary,
    pain_points: (company.pain_points || []).join('; '),
    contact_name: [person.first_name, person.last_name].filter(Boolean).join(' ') || 'Unknown',
    contact_title: person.title || '',
    contact_email: person.email || '',
    product_description: $('Set Search Params').item.json.product_description
  }
}];

values.content:
=Write a cold outreach email.

Our product: {{ $json.product_description }}
Company: {{ $json.company_name }}
Contact: {{ $json.contact_name }}, {{ $json.contact_title }}
Summary: {{ $json.analysis_summary }}
Pain points: {{ $json.pain_points }}

Return JSON:
{"subject": "...", "body": "..."}

Max 150 words. One CTA. No buzzwords.

parameters.jsCode:
const row = $('Merge Contact Data').item.json;
let email = { subject: '', body: '' };
try {
  const raw = $input.first().json.message?.content || $input.first().json.text || '{}';
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  email = JSON.parse(cleaned);
} catch (e) {
  email = { subject: 'Follow up', body: 'Could not generate email.' };
}
return [{
  json: {
    timestamp: new Date().toISOString(),
    company_name: row.company_name,
    website: row.website,
    industry: row.industry,
    analysis_summary: row.analysis_summary,
    contact_name: row.contact_name,
    contact_title: row.contact_title,
    contact_email: row.contact_email,
    email_subject: email.subject,
    email_body: email.body,
    status: 'draft'
  }
}];
